                HistoryFigure("Chico Xavier","1910–2002","Psicógrafo de Pedro Leopoldo e Uberaba, a quem são atribuídas centenas de obras psicografadas, entre elas a série de André Luiz, iniciada com Nosso Lar (1944)."),
                HistoryFigure("Divaldo Pereira Franco","n. 1927","Orador e psicógrafo baiano ligado à Mansão do Caminho, obra assistencial de Salvador; um dos divulgadores espíritas mais conhecidos do século XX."),
                HistoryFigure("Waldo Vieira","1932–2015","Médico e psicógrafo, parceiro de Chico Xavier em obras conjuntas nas décadas de 1950–60, antes de seguir o seu próprio campo de estudos."),
            ),
            timeline=listOf(
                HistoryEvent("1848","Hydesville","As irmãs Fox relatam pancadas interpretadas como comunicações de um espírito; arranca a vaga do espiritualismo moderno."),
                HistoryEvent("1857","O Livro dos Espíritos","Kardec publica em Paris a obra fundadora da codificação, com 1019 perguntas e respostas."),
                HistoryEvent("1858","Revue Spirite","Kardec funda a Revue Spirite e a Société parisienne des études spirites, criando a rede de discussão do movimento."),
                HistoryEvent("1861","O Livro dos Médiuns","O manual prático das comunicações mediúnicas."),
                HistoryEvent("1864","O Evangelho Segundo o Espiritismo","A leitura moral espírita dos Evangelhos."),
                HistoryEvent("1865","O Céu e o Inferno","Sobre a justiça divina e o destino após a morte."),
                HistoryEvent("1868","A Génese","Criação, milagres e predições; fecha o ciclo dos cinco livros de base."),
                HistoryEvent("1869","Morte de Kardec","Kardec morre em Paris, com a codificação publicada e uma rede de correspondentes em vários países."),
                HistoryEvent("1884","Federação Espírita Brasileira","Fundada no Rio de Janeiro, a 2 de janeiro, por Augusto Elias da Silva e outros participantes."),
                HistoryEvent("1932","Parnaso de além-túmulo","Primeiro livro de Chico Xavier; início da sua trajetória editorial como psicógrafo."),
                HistoryEvent("1944","Nosso Lar","Publicado o primeiro romance da série atribuída ao espírito André Luiz, psicografado por Chico Xavier."),
            ),
            practices=listOf(
                HistorySection("Estudo e reuniões de estudo","Nos centros espíritas, o estudo regular das obras de base — muitas vezes em grupos de Estudo Sistematizado da Doutrina Espírita (ESDE) — é a prática formativa central: leitura comentada, perguntas e aplicação moral ao quotidiano.",emptyList()),
                HistorySection("Reuniões mediúnicas","Sessões fechadas, com um grupo reduzido e orientação própria, dedicadas à comunicação com espíritos e ao atendimento de participantes e de espíritos que a tradição considera sofredores. Kardec dedicou-lhes O Livro dos Médiuns.",emptyList()),
                HistorySection("O passe e a água fluidificada","O passe é a imposição de mãos de um aplicador sobre quem o recebe, entendido pela tradição como transmissão de energias restauradoras. A água fluidificada, presente durante os trabalhos, é depois consumida com a mesma intenção.",emptyList()),
                HistorySection("Evangelho no Lar","Reunião semanal doméstica: leitura de um trecho de O Evangelho Segundo o Espiritismo, comentários breves e prece, com a família reunida durante cerca de meia hora.",emptyList()),
                HistorySection("Caridade e assistência","A máxima «Fora da caridade não há salvação» traduz-se em obras assistenciais mantidas pelos centros: distribuição de alimentos, enxovais, creches e instituições como a Mansão do Caminho, em Salvador.",emptyList()),
            )),
        HistoryArticle(id="christianity",title="Cristianismo",symbol="✝",description="Do contexto judaico do século I à pluralidade de igrejas.",area=false,
            sections=listOf(
                HistorySection("Século I · Judeia e mundo romano","O cristianismo formou-se entre [[judaism|comunidades judaicas]] do Mediterrâneo oriental, sob domínio romano. Jesus de Nazaré é a figura central; os evangelhos são simultaneamente textos religiosos e fontes históricas que exigem análise crítica. A crucificação pertence à reconstrução histórica da sua vida; a ressurreição é uma afirmação de fé cristã. As primeiras comunidades interpretaram a vida de Jesus a partir das Escrituras judaicas e difundiram a mensagem por cidades do Império Romano. A expansão envolveu viagens, correspondência e redes urbanas.",listOf(1)),
                HistorySection("Comunidades e transmissão textual","As cartas de Paulo e as narrativas evangélicas testemunham debates sobre a relação com a lei judaica, a composição das comunidades e a identidade de Jesus. A Bíblia cristã reúne textos de épocas e géneros diferentes. Não é um livro escrito de uma só vez nem por um único autor. A história do cânone deve distinguir-se da história de cada manuscrito, tradução e edição. As comunidades conservaram práticas de oração, batismo e refeição ritual, com interpretações que se transformaram ao longo do tempo.",listOf(1)),
                HistorySection("313 e 330 · transformação imperial","A legalização do cristianismo em 313 alterou a sua presença pública. Em 330, a transferência da capital imperial para Constantinopla ajudou a deslocar o centro político para o Mediterrâneo oriental. Igrejas, imagens, inscrições e objetos litúrgicos passaram a documentar de maneira crescente o patrocínio cristão. A mudança foi gradual: não eliminou imediatamente práticas antigas nem criou uniformidade doutrinal. O estudo histórico deve acompanhar as relações entre autoridades religiosas, governantes e populações, em vez de atribuir todas as transformações a uma decisão isolada.",listOf(2)),
                HistorySection("Niceia, 325 · formular a doutrina","O imperador Constantino convocou o concílio de Niceia, na Ásia Menor, em 325. As discussões envolveram a relação entre o Filho e o Pai e posições associadas a Ário. O acontecimento mostra a articulação entre poder imperial, redes episcopais e definição doutrinal. A decisão conciliar é um facto da história das instituições; as afirmações sobre a natureza divina de Cristo pertencem à teologia cristã. A Biblioteca Vaticana conserva e apresenta testemunhos relacionados com esta história. Sendo uma instituição católica, a sua descrição deve ser contextualizada ao lado da investigação crítica, sobretudo quando adota a linguagem normativa da tradição.",listOf(4)),
                HistorySection("Século XVI · reformas europeias","Em 1517, as teses de Martinho Lutero em Wittenberg tornaram-se um marco convencional da Reforma protestante. As mudanças tiveram antecedentes e não constituíram um movimento único. Questões sobre indulgências, autoridade, Escritura e salvação cruzaram-se com a imprensa e a política. Na Inglaterra, a separação de Roma ocorreu através de medidas parlamentares entre 1533 e 1536; o Ato de Supremacia de 1534 declarou o rei chefe da Igreja inglesa. O Livro de Oração Comum de 1549 organizou a liturgia no reinado de Eduardo VI. Estes percursos diferentes ajudam a explicar a formação de igrejas protestantes distintas, em vez de uma única instituição fundada num só dia.",listOf(5,6)),
                HistorySection("Diversidade, contemplação e memória","O cristianismo desenvolveu tradições católicas, ortodoxas e protestantes, além de antigas igrejas orientais com percursos próprios. A história inclui cooperação, reforma, conflitos e perseguições; nenhuma comunidade contemporânea representa sozinha todo esse passado. Agostinho de Hipona, na Antiguidade tardia, e os autores ligados à literatura contemplativa são exemplos de diferentes modos de pensar a vida cristã. Obras como Confissões e Imitação de Cristo devem ser lidas no seu contexto. Estudar a sua influência histórica não obriga a aceitar nem a rejeitar os ensinamentos religiosos que apresentam.",listOf(1,2)),
            ),figures=listOf(HistoryFigure("Jesus de Nazaré","c. 6–4 a.C. – c. 30 d.C.","Pregador judeu da Galileia, figura central do cristianismo. Os evangelhos apresentam o seu ensino centrado no Reino de Deus, nas parábolas e no amor a Deus e ao próximo; foi crucificado em Jerusalém sob Pôncio Pilatos. Os cristãos confessam-no como Cristo, o Ungido, Filho de Deus e ressuscitado — afirmação de fé que a história regista como o motor do movimento que dele nasceu."),HistoryFigure("Paulo de Tarso","c. 5 – c. 64","De perseguidor das primeiras comunidades a missionário itinerante pelo Mediterrâneo oriental. As suas cartas — os textos mais antigos do Novo Testamento — formularam temas centrais como a graça, a fé e a abertura da mensagem aos não judeus, e moldaram a teologia cristã de todas as épocas."),HistoryFigure("Agostinho de Hipona","354–430","Bispo norte-africano, autor das Confissões e de A Cidade de Deus. A sua reflexão sobre a graça, o pecado, o tempo e a história interior marcou profundamente o cristianismo ocidental — o católico e, séculos depois, também o protestante."),HistoryFigure("Bento de Núrsia","c. 480–547","Autor da Regra que organizou a vida monástica ocidental: oração, trabalho e leitura numa comunidade estável. Os mosteiros beneditinos conservaram e copiaram grande parte da literatura antiga e tornaram-se centros de cultura na Europa medieval."),HistoryFigure("Francisco de Assis","1181/82–1226","Filho de um mercador italiano que renunciou à riqueza para viver a pobreza evangélica. Fundou a ordem dos Frades Menores e tornou-se símbolo de simplicidade, fraternidade e cuidado com a criação; é admirado muito para lá da Igreja católica."),HistoryFigure("Tomás de Aquino","1225–1274","Frade dominicano e teólogo, autor da Suma Teológica. Procurou articular fé e razão, integrando Aristóteles no pensamento cristão; a sua obra tornou-se referência maior da teologia católica e da filosofia escolástica."),HistoryFigure("Martinho Lutero","1483–1546","Monge e professor em Wittenberg; as 95 teses de 1517, sobre as indulgências, tornaram-se o marco convencional da Reforma protestante. Defendeu a autoridade da Escritura e a justificação pela fé, traduziu a Bíblia para alemão e inspirou igrejas luteranas em todo o mundo."),HistoryFigure("João Calvino","1509–1564","Reformador francês radicado em Genebra, autor das Institutas da Religião Cristã. A sua teologia — soberania de Deus, Escritura, disciplina da igreja — deu forma à tradição reformada, com influência duradoura na Europa e na América do Norte."),HistoryFigure("Teresa de Ávila","1515–1582","Religiosa carmelita espanhola, mística e escritora (O Castelo Interior, Livro da Vida). Reformou a ordem do Carmelo, com João da Cruz, e deixou uma das descrições mais influentes da vida de oração na tradição cristã; foi proclamada Doutora da Igreja em 1970.")),timeline=listOf(HistoryEvent("c. 6–4 a.C.","Nascimento de Jesus","Jesus nasce na Judeia sob domínio romano, ainda no reinado de Herodes. A data exata é incerta; os relatos são os evangelhos de Mateus e de Lucas."),HistoryEvent("c. 27–30","Ministério e crucificação","Pregação na Galileia e na Judeia, crucificação em Jerusalém sob Pôncio Pilatos e, segundo a fé das primeiras comunidades, o anúncio da ressurreição."),HistoryEvent("c. 45–60","Paulo e as primeiras cartas","As viagens missionárias de Paulo e as cartas que escreveu às comunidades do Mediterrâneo são os testemunhos escritos mais antigos do cristianismo."),HistoryEvent("c. 65–100","Evangelhos e comunidades","São redigidos os evangelhos e os restantes textos que viriam a formar o Novo Testamento; as comunidades organizam-se nas cidades do Império."),HistoryEvent("313","Édito de Milão","Constantino e Licínio legalizam o cristianismo no Império Romano; termina a era das perseguições oficiais."),HistoryEvent("325","Concílio de Niceia","Primeiro concílio ecuménico: formula o credo sobre a relação entre o Pai e o Filho e condena a posição de Ário."),HistoryEvent("380","Religião do Império","O édito de Tessalónica faz do cristianismo niceno a religião oficial do Império Romano."),HistoryEvent("1054","Grande Cisma","A rutura entre Roma e Constantinopla separa o cristianismo latino do Ocidente do cristianismo grego do Oriente — católicos e ortodoxos."),HistoryEvent("1517","Teses de Lutero","As 95 teses em Wittenberg dão o início visível à Reforma protestante; seguem-se décadas de reformas, de resposta católica e de conflitos na Europa."),HistoryEvent("1545–1563","Concílio de Trento","A resposta doutrinal e disciplinar da Igreja católica à Reforma: reforma interna, seminários e catecismo."),HistoryEvent("1962–1965","Concílio Vaticano II","A Igreja católica abre-se ao diálogo com o mundo moderno, reforma a liturgia e dá passos de aproximação às outras igrejas cristãs.")),practices=listOf(HistorySection("Batismo","Rito de entrada na comunidade cristã, com água, em nome da Trindade. As tradições diferem sobre quem o recebe — adultos que professam a fé, em muitas igrejas evangélicas e batistas; também crianças, nas igrejas católica e ortodoxas e em várias protestantes históricas — e sobre a forma, imersão ou aspersão.",listOf()),HistorySection("Eucaristia","A partilha do pão e do vinho em memória da última ceia de Jesus, centro da liturgia cristã. Chamada missa ou eucaristia nas tradições católica e ortodoxas e ceia do Senhor em muitas protestantes, é entendida de modos diferentes quanto à presença de Cristo, mas celebrada por praticamente todas as igrejas.",listOf()),HistorySection("Oração e liturgia","Da oração pessoal silenciosa às liturgias comunitárias com leituras, salmos, hinos e sermão. O Pai-Nosso, ensinado por Jesus, é a oração comum a todos os cristãos; mosteiros e catedrais desenvolveram ciclos diários de oração, a liturgia das horas.",listOf()),HistorySection("Jejum e Quaresma","Tempos de penitência e de preparação, em especial a Quaresma — os quarenta dias antes da Páscoa — e, na tradição oriental, jejuns mais longos e rigorosos. O jejum combina abstinência alimentar com oração e partilha com os pobres.",listOf()),HistorySection("Peregrinação","A viagem a lugares de memória cristã: Jerusalém e a Terra Santa, Roma, Santiago de Compostela e santuários marianos como Fátima e Lourdes. Prática antiga, mantém-se viva em todas as grandes tradições cristãs.",listOf())),sources=listOf(
                HistorySource("Khan Academy · Christianity, Merry Wiesner-Hanks","https://www.khanacademy.org/humanities/world-history-project-ap-preview/x7515b0ca3395d084:review-introduction-to-world-history/x7515b0ca3395d084:0-2development-of-portable-belief-systems/a/read-christianity-appreview","Estudo histórico"),
                HistorySource("Museu Bizantino e Cristão · From the Ancient World to Byzantium","https://www.byzantinemuseum.gr/en/exhibitions/47/permanent-exhibition/from-the-ancient-world-to-byzantium/6/from-the-ancient-world-to-byzantium","Estudo histórico"),
                HistorySource("Vaticano · Bíblia em português","https://www.vatican.va/archive/bible/index_po.htm","Fonte textual da tradição; direitos por edição"),
                HistorySource("Biblioteca Vaticana · On the 1700th Anniversary of the Council of Nicaea","https://www.vaticanlibrary.va/newsletter/202506EN.pdf","Fonte institucional católica"),
                HistorySource("Pew Research Center · Catholic-Protestant Divide in Western Europe","https://www.pewresearch.org/religion/2017/08/31/five-centuries-after-reformation-catholic-protestant-divide-in-western-europe-has-faded/","Estudo histórico"),
                HistorySource("Parlamento britânico · The Reformation","https://www.parliament.uk/about/living-heritage/transformingsociety/private-lives/religion/overview/reformation/","Estudo histórico"),
            ),related=listOf("judaism","islam","mysticism"),concepts="Evangelhos · graça · amor ao próximo · contemplação",conceptItems=listOf(HistoryConcept("Evangelhos","Os quatro relatos canónicos da vida, do ensino, da morte e da ressurreição de Jesus (Mateus, Marcos, Lucas e João). Formam o coração do Novo Testamento e a fonte primeira da fé cristã sobre quem Jesus foi e o que ensinou."),HistoryConcept("Graça","O favor gratuito de Deus para com a humanidade, independente de méritos: no cristianismo, a salvação é dom recebido pela fé e não recompensa conquistada. A noção ganhou peso especial nas disputas da Reforma sobre fé e obras."),HistoryConcept("Amor ao próximo","O mandamento que Jesus apresenta, a par do amor a Deus, como resumo de toda a Lei: amar o próximo como a si mesmo, incluindo o inimigo. É o critério ético central do cristianismo e o fundamento da sua tradição de caridade."),HistoryConcept("Contemplação","A oração silenciosa de atenção e de presença diante de Deus, para lá das palavras e dos pedidos. Desenvolvida no monaquismo e na mística cristã, procura a união amorosa com Deus já nesta vida."))),
        HistoryArticle(id="judaism",title="Judaísmo e Cabala",symbol="✡",description="Israel antigo, interpretação rabínica e tradições místicas judaicas.",area=false,
            sections=listOf(
                HistorySection("Antigo Israel · memória e documentação","O judaísmo tem raízes nas tradições do antigo Israel, no Mediterrâneo oriental. As narrativas de Abraão e Moisés são centrais na memória religiosa, mas não devem ser convertidas automaticamente em biografias confirmadas por fontes externas. Textos bíblicos, inscrições e vestígios materiais têm naturezas e limites diferentes. O estudo histórico procura compreender a formação das comunidades, a transmissão das leis e as transformações das práticas. A ideia religiosa de aliança é apresentada como uma maneira judaica de interpretar a relação entre o povo e Deus.",listOf(1)),
                HistorySection("Jerusalém · 586 a.C. e 70 d.C.","A destruição do Primeiro Templo pelos babilónios, em 586 a.C., e a do Segundo Templo pelos romanos, em 70 d.C., são dois marcos diferentes da história de Jerusalém. Não devem ser confundidos nem usados para datar automaticamente todas as narrativas bíblicas. A memória dessas perdas foi transmitida em textos e práticas comunitárias. A história judaica posterior inclui comunidades dispersas, centros de estudo e formas diversas de adaptação. A continuidade de uma tradição religiosa não significa que as instituições, as fronteiras ou as línguas tenham permanecido iguais durante todos esses séculos.",listOf(3)),
                HistorySection("Jerusalém e a tradição de interpretação","A história judaica não se limita ao território de origem. Comunidades da diáspora participaram na transmissão de textos e instituições. A destruição do Segundo Templo de Jerusalém pelos romanos, em 70 d.C., é um marco decisivo. O judaísmo rabínico desenvolveu o estudo e a interpretação da Torá através de debates preservados na Mishná e nos Talmudes. Estes textos registam posições diferentes: não são uma declaração uniforme de todos os judeus de todas as épocas. A vida comunitária envolve também práticas familiares, calendário e obrigações religiosas.",listOf(1,3)),
                HistorySection("Idade Média · formação da Cabala","Cabala designa um conjunto de tradições místicas judaicas e não todo o judaísmo. A sua formação medieval deve distinguir-se das origens remotas que os próprios textos reivindicam. O Sefer Yetzirah tem uma transmissão textual complexa. O Zohar, ligado à história da Cabala na Península Ibérica do século XIII, apresenta uma atribuição tradicional a uma autoridade antiga que não resolve a questão histórica da composição. Sefirot e interpretações simbólicas da criação pertencem ao vocabulário destas correntes. A antiguidade atribuída a um ensinamento não equivale à data do manuscrito que o conserva.",listOf(2,6)),
                HistorySection("Safed · século XVI e Isaac Luria","Isaac Luria, que viveu entre 1534 e 1572, nasceu em Jerusalém, cresceu no Egito e passou os últimos anos da vida em Safed, na Galileia. Tornou-se uma figura central na história da Cabala. Muito do que se conhece dos seus ensinamentos foi transmitido por discípulos, em especial Chaim Vital. Uma carta preservada na Biblioteca Nacional de Israel permite observar relações concretas entre pessoas e comunidades, para além das descrições místicas. O exemplo mostra a importância de distinguir um documento contemporâneo de uma biografia devocional posterior e de identificar quem transmitiu as palavras atribuídas a um mestre.",listOf(4,5)),
                HistorySection("Continuidade e diversidade","A tradição cabalística conheceu novas interpretações e centros de estudo; não permaneceu uma escola única. É necessário distinguir a Cabala judaica das apropriações cristãs e de formas modernas de esoterismo que usam terminologia semelhante. A Torá, o Tanakh e a literatura rabínica continuam a fornecer referências mais amplas para o estudo judaico. Fontes antigas podem conter categorias e juízos hoje contestados; devem ser contextualizadas. O facto de uma prática, instituição ou texto ser historicamente documentado não prova as afirmações sobrenaturais nele expressas.",listOf(1,2)),
            ),sources=listOf(
                HistorySource("PBS · Global Connections: Religion","https://www.pbs.org/wgbh/globalconnections/mideast/themes/religion/index.html","Estudo histórico"),
                HistorySource("Jewish Encyclopedia · Cabala","https://www.jewishencyclopedia.com/articles/3878-cabala","Enciclopédia histórica de 1901–1906; terminologia a contextualizar"),
                HistorySource("Sefaria · Destruction of the Temple","https://www.sefaria.org/topics/destruction-of-the-temple?no_applink=1&sort=Relevance&tab=notable-sources","Biblioteca de textos da tradição"),
                HistorySource("Biblioteca Nacional de Israel · A Letter Sent to Isaac Luria","https://blog.nli.org.il/en/djm-ari-letter/","Estudo histórico"),
                HistorySource("Cambridge University Library · Lionising Luria: Mosseri III.232","https://www.lib.cam.ac.uk/collections/departments/taylor-schechter-genizah-research-unit/fragment-month/fotm-2024/fragment-1","Estudo histórico"),
                HistorySource("Sefaria · Zohar: About This Text","https://www.sefaria.org/Zohar%2C_Bereshit.102.432?lang=en&with=About","Biblioteca textual; história da atribuição"),
            ),related=listOf("christianity","islam","mysticism"),concepts="Torá · aliança · mitzvot · interpretação · sefirot",conceptItems=listOf(HistoryConcept("Torá","O ensino divino revelado a Moisés, cujo núcleo são os cinco primeiros livros da Bíblia hebraica (Génesis a Deuteronómio). No judaísmo rabínico, à Torá escrita junta-se a Torá oral: a tradição de interpretação recolhida no Talmude."),HistoryConcept("Aliança","A relação pactuada entre Deus e Israel: Deus escolhe e protege o povo; Israel responde com fidelidade à Lei. A aliança, celebrada com Abraão e renovada no Sinai, estrutura a identidade e a história judaicas."),HistoryConcept("Mitzvot","Os mandamentos da Torá — tradicionalmente 613 — que ordenam a vida religiosa, ética e quotidiana: do sábado e das festas à alimentação (cashrut), à justiça e ao cuidado dos pobres. Cumprir os mitzvot é a forma concreta da fidelidade à aliança."),HistoryConcept("Interpretação","A leitura comentada das Escrituras, que no judaísmo é inseparável do próprio texto: gerações de rabis debateram cada verso (midrash, Talmude), assumindo que o sentido se desdobra em camadas e que o debate também é uma forma de fidelidade."),HistoryConcept("Sefirot","Na Cabala, as dez emanações ou atributos através dos quais o Deus infinito (Ein Sof) se revelaria e sustentaria o mundo — de Keter (coroa) a Malkhut (reino). O equilíbrio entre elas descreve tanto a estrutura do divino como o caminho espiritual humano."))),
        HistoryArticle(id="islam",title="Islão e sufismo",symbol="☪",description="Da Arábia do século VII às culturas e vias espirituais islâmicas.",area=false,
            sections=listOf(
                HistorySection("Século VII · Meca e Medina","O Islão surgiu na Península Arábica no século VII, associado à pregação de Muhammad. O Alcorão é entendido pelos muçulmanos como revelação divina; o historiador estuda a transmissão do texto e a formação das comunidades sem transformar essa crença numa conclusão científica. A Hégira, deslocação de Meca para Medina em 622, constitui o ponto de referência do calendário islâmico. A comunidade desenvolveu relações religiosas, sociais e políticas. A distinção entre o que as fontes religiosas narram e o que pode ser corroborado por outros documentos é essencial.",listOf(1)),
                HistorySection("Sucessão e expansão","Depois da morte de Muhammad, em 632, as disputas pela liderança contribuíram para a diferenciação histórica de sunitas e xiitas. Estas designações não se esgotam numa decisão inicial: doutrinas e instituições desenvolveram-se posteriormente. A expansão dos poderes islâmicos levou a novos centros políticos e culturais fora da Arábia. Tradução, comércio, administração e produção artística participaram nessa história. Não se deve confundir o crescimento de um império com a conversão imediata de toda a população dos territórios que governava.",listOf(1,2)),
                HistorySection("Práticas sufistas e diversidade regional","O sufismo reúne vias de cultivo espiritual presentes em diferentes ambientes islâmicos. Ascetismo, recordação de Deus e orientação por mestres são temas recorrentes, mas não existe uma prática única comum a todos os grupos. Ordens e linhagens desenvolveram-se ao longo da história medieval. As práticas sufistas atravessam fronteiras entre comunidades sunitas e xiitas. Rumi e outros autores de poesia mística integram um universo literário em que as palavras exigem interpretação; a linguagem de união com Deus expressa ensinamentos religiosos.",listOf(2,3)),
                HistorySection("Arte, instituições e transformações modernas","A presença sufista é documentada do Norte de África ao sul da Ásia, em contextos que incluem tanto retiros ascéticos como relações com cortes. Mestres, santuários e confrarias tiveram influência cultural e política. Em 1925, a República da Turquia dissolveu as ordens sufistas, um exemplo concreto de transformação institucional moderna. A sobrevivência de práticas e a circulação global dos textos não eliminam a diversidade local. A história do sufismo deve, por isso, acompanhar comunidades, objetos e instituições, sem o apresentar como uma religião única separada do Islão.",listOf(3)),
            ),sources=listOf(
                HistorySource("Metropolitan Museum · The Birth of Islam","https://www.metmuseum.org/essays/the-birth-of-islam","Estudo histórico"),
                HistorySource("Metropolitan Museum · Islamic Art: Frequently Asked Questions","https://www.metmuseum.org/fr/learn/educators/curriculum-resources/art-of-the-islamic-world/introduction/frequently-asked-questions","Estudo histórico"),
                HistorySource("Metropolitan Museum · Art of the Sufis","https://www.metmuseum.org/fr/essays/art-of-the-sufis","Estudo histórico"),
            ),related=listOf("judaism","christianity","mysticism"),concepts="Tawhid · oração · dhikr · ihsan · ética",conceptItems=listOf(HistoryConcept("Tawhid","A afirmação da unicidade absoluta de Deus, centro do islão: Deus é um, sem associados nem divisões. É o conteúdo da profissão de fé («Não há deus senão Deus») e o critério pelo qual se julga qualquer desvio, como a idolatria."),HistoryConcept("Oração","A salat, oração ritual feita cinco vezes ao dia, em horários fixos, com ablução prévia e movimentos prescritos, voltado para Meca. É um dos cinco pilares do islão e a forma quotidiana de ligação direta do crente com Deus, sem intermediários."),HistoryConcept("Dhikr","A recordação de Deus pela repetição dos seus nomes ou de fórmulas breves, em voz alta ou em silêncio. Praticado por todos os muçulmanos e desenvolvido de forma intensa no sufismo, procura tornar a presença divina contínua na consciência."),HistoryConcept("Ihsan","A excelência espiritual: adorar Deus como se O víssemos, na formulação de um dito do Profeta. Terceira dimensão da religião, ao lado da fé e da prática, designa a sinceridade e a beleza interior com que cada ato é feito."),HistoryConcept("Ética","No islão, a conduta — justiça, honestidade, generosidade, cuidado da família e dos vizinhos — é parte inseparável da fé e não um apêndice dela. O Corão e o exemplo do Profeta fazem do caráter (akhlaq) uma medida do crente."))),
        HistoryArticle(id="taoism",title="Taoismo",symbol="☯",description="Textos clássicos, comunidades religiosas e história chinesa.",area=false,
            sections=listOf(
                HistorySection("China antiga · textos e categorias","Taoismo, também grafado daoismo, é uma designação ampla para tradições chinesas com dimensões filosóficas, religiosas e rituais. A classificação de Laozi e Zhuangzi como representantes de uma mesma escola foi construída retrospectivamente por historiadores. Os textos nasceram num ambiente de debate sobre governo, conduta e formas de viver. Não existiu desde o início uma instituição única chamada taoismo que dirigisse todos os autores. A própria distinção moderna entre filosofia e religião não reproduz perfeitamente as categorias dos seus praticantes.",listOf(1)),
                HistorySection("Laozi e a história do Dao De Jing","A tradição associa o Dao De Jing a Laozi. A existência e a biografia desta figura são discutidas e as fontes não permitem afirmar todos os episódios transmitidos. Manuscritos e variantes mostram uma história textual mais complexa do que a ideia de um livro escrito de uma só vez. Dao, de, wu wei e ziran são conceitos com diferentes interpretações éticas, políticas e religiosas. A tradução de wu wei como ausência de ação pode induzir em erro quando sugere simples passividade; o contexto é indispensável.",listOf(2)),
                HistorySection("Zhuangzi e desenvolvimentos posteriores","O Zhuangzi reúne materiais de diferentes autores e períodos, não uma transcrição integral das palavras de um só mestre. Diálogos, humor e narrativas exploram perspetiva, conhecimento e limites das convenções. Nos séculos seguintes, comentários e interpretações aproximaram e distinguiram estes textos de outras correntes chinesas. A formação de comunidades religiosas na época Han tardia acrescentou estruturas de mestres, práticas rituais e novas escrituras. A tradição dos Mestres Celestes remete a sua origem para Zhang Daoling e para uma revelação datada tradicionalmente de 142 d.C.; o caráter revelado pertence ao relato religioso.",listOf(1,3)),
                HistorySection("Transmissão e leitura contemporânea","Taoismo, confucionismo e budismo influenciaram-se mutuamente ao longo da história chinesa, sem perderem todas as diferenças. O estudo de manuscritos, comentários e instituições mostra continuidades e mudanças. O símbolo yin-yang, aqui usado para orientação visual, pertence a um repertório chinês mais amplo e não é exclusivo do taoismo. Edições populares que reduzem a tradição a frases motivacionais não substituem o estudo do contexto. Longevidade sobrenatural e outras promessas religiosas devem ser descritas como crenças, não como resultados médicos estabelecidos.",listOf(1,2)),
            ),sources=listOf(
                HistorySource("Stanford Encyclopedia · Daoism","https://plato.stanford.edu/entries/daoism/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Laozi","https://plato.stanford.edu/entries/laozi/","Estudo histórico"),
                HistorySource("Internet Encyclopedia of Philosophy · Daoist Philosophy","https://iep.utm.edu/daoismdaoist-philosophy/","Estudo histórico"),
            ),related=listOf("confucianism","buddhism","philosophy"),concepts="Dao · de · wu wei · ziran",conceptItems=listOf(HistoryConcept("Dao","O Caminho: a realidade última e o curso natural de todas as coisas, que não se deixa definir por palavras — «o Dao que pode ser nomeado não é o Dao eterno», abre o Daodejing. Viver bem é alinhar-se com ele, em vez de o forçar."),HistoryConcept("De","A virtude ou potência própria de cada ser quando está em harmonia com o Dao: a eficácia natural que não se impõe. No Daodejing, é o modo como o Dao se manifesta nas coisas e nas pessoas."),HistoryConcept("Wu wei","A ação sem forçar: agir em consonância com o curso das coisas, sem esforço contrário nem interferência excessiva. É o princípio prático do taoismo para a vida pessoal e para o governo — o sábio faz sem fazer."),HistoryConcept("Ziran","O assim por si mesmo: o estado espontâneo e natural das coisas quando nada as constrange. Ideal de autenticidade no taoismo — deixar cada ser seguir a sua natureza é a forma mais alta de ordem."))),
        HistoryArticle(id="confucianism",title="Confucionismo",symbol="儒",description="Ética, ritual e educação na história da Ásia oriental.",area=false,
            sections=listOf(
                HistorySection("Estado de Lu · Confúcio","Confúcio, ou Kongzi, está associado ao estado de Lu, na China antiga. As datas de 551–479 a.C. são tradicionais. Foi recordado como mestre, intérprete do ritual e referência para a conduta política. Os relatos conservados não oferecem acesso direto e uniforme a tudo o que disse. A imagem de Confúcio transformou-se com as necessidades de cada período. Os Analectos reúnem diálogos e ensinamentos transmitidos por comunidades de seguidores, em vez de constituírem um livro autobiográfico do mestre.",listOf(1)),
                HistorySection("Debate ético e vida social","Ren, traduzido frequentemente por humanidade, e li, relacionado com ritual e formas de comportamento, são conceitos centrais. Família, educação e governo são pensados em relação com a formação do caráter. A tradição não pode ser descrita apenas como obediência automática: inclui debates sobre responsabilidade e conduta de governantes e governados. Mêncio e Xunzi são referências de desenvolvimentos posteriores do pensamento associado aos letrados. Convém distinguir o ideal apresentado nos textos da maneira como autoridades históricas o usaram.",listOf(1,2)),
                HistorySection("Séculos IV–III a.C. · Mêncio e Xunzi","Mêncio, no século IV a.C., e Xunzi, no século III a.C., representam desenvolvimentos diferentes da tradição. Mêncio é conhecido pela tese de que a natureza humana é boa e pela reflexão sobre o cultivo das disposições morais. Xunzi atribuiu um papel decisivo à aprendizagem e ao ritual na transformação da conduta. As formulações não se reduzem a um acordo total sob a autoridade de Confúcio. As coleções que conservam os seus argumentos também têm uma história de compilação e edição. A diversidade interna faz parte do confucionismo desde a Antiguidade, não apenas das interpretações modernas.",listOf(3,4)),
                HistorySection("China imperial · instituições e interpretação","Durante a dinastia Han, especialistas nos clássicos receberam lugares no aparelho governativo e Confúcio tornou-se uma autoridade cultural. A leitura dos textos passou a integrar a formação dos letrados e a legitimação do governo. Práticas de culto e rituais coexistiram com o estudo ético. Por isso, a classificação como religião ou filosofia depende dos aspetos observados e das definições usadas. As instituições chinesas também conviveram com outras tradições, incluindo taoismo e budismo.",listOf(1,2)),
                HistorySection("Song e circulação internacional","No período Song, de 960 a 1279, desenvolveram-se correntes hoje chamadas neoconfucionistas. Zhu Xi, que viveu entre 1130 e 1200, integrou os Analectos num programa dos Quatro Livros influente na China, Coreia e Japão. A tradição foi assim reinterpretada em contextos que já conheciam o budismo. Missionários e autores europeus voltaram a transformá-la ao descrevê-la para outros públicos. O nome confucionismo agrupa uma história diversa; não garante uma doutrina única de todos os povos da Ásia oriental.",listOf(1)),
                HistorySection("1472–1529 · Wang Yangming","Wang Yangming foi um funcionário, general e filósofo da China Ming. Criticou aspetos da interpretação associada a Zhu Xi e tornou-se conhecido pela discussão da unidade entre conhecer e agir. A sua biografia, situada entre 1472 e 1529, mostra que o confucionismo continuou a produzir debates muito depois da formação dos clássicos. Educação, exame e serviço público eram contextos concretos desse pensamento. Não se deve converter a história da tradição numa sequência de mestres que apenas repetiram as mesmas ideias: a interpretação dos textos também serviu para formular discordâncias.",listOf(5)),
            ),sources=listOf(
                HistorySource("Stanford Encyclopedia · Confucius","https://plato.stanford.edu/entries/confucius/","Estudo histórico"),
                HistorySource("National Geographic · Chinese Religions and Philosophies","https://education.nationalgeographic.org/resource/chinese-religions-and-philosophies/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Mencius","https://plato.stanford.edu/entries/mencius/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Xunzi","https://plato.stanford.edu/entries/xunzi/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Wang Yangming","https://plato.stanford.edu/entries/wang-yangming/","Estudo histórico"),
            ),related=listOf("taoism","philosophy","religions"),concepts="Ren · li · aprendizagem · responsabilidade · governo",conceptItems=listOf(HistoryConcept("Ren","A humanidade ou benevolência: a virtude maior do confucionismo, que se realiza nas relações concretas — amar os outros, na fórmula de Confúcio. É a qualidade interior que faz da pessoa exemplar (junzi) um centro de harmonia para os que a rodeiam."),HistoryConcept("Li","Os ritos e as formas apropriadas de conduta: cerimónias, etiqueta, respeito pelas hierarquias e pelos antepassados. Para Confúcio, o li não é formalismo vazio: é a moldura que educa os sentimentos e torna a convivência possível."),HistoryConcept("Aprendizagem","O estudo constante dos clássicos, da história e da conduta dos sábios antigos é, no confucionismo, o caminho principal de aperfeiçoamento moral. Confúcio apresenta-se como um transmissor que aprende sem se cansar e ensina sem se fartar."),HistoryConcept("Responsabilidade","Cada pessoa ocupa um lugar numa rede de relações — governante e súbdito, pais e filhos, mais velhos e mais novos, amigos — e deve cumprir o que esse lugar exige. É a retificação dos nomes: que cada um seja de facto aquilo que o seu nome declara."),HistoryConcept("Governo","Para o confucionismo, governa-se antes de mais pelo exemplo moral e pela educação, e não pela força nem pelas leis penais: se o governante for reto, quem ousará não ser reto? A política é a ética aplicada à escala do Estado."))),
        HistoryArticle(id="hermeticism",title="Hermetismo",symbol="⚚",description="Textos greco-egípcios e a sua receção medieval e renascentista.",area=false,
            sections=listOf(
                HistorySection("Egito romano · atribuições e textos","Hermes Trismegisto é uma figura de autoridade tradicional que aproxima repertórios gregos e egípcios. O nome não identifica um autor histórico comprovado de todos os textos que lhe foram atribuídos. Os tratados filosóficos do Corpus Hermeticum e o Asclepius pertencem ao ambiente intelectual da Antiguidade imperial e tardia. Discursos sobre o intelecto, o cosmos e o conhecimento religioso devem ser lidos nesse contexto. Outros escritos herméticos tratam de astrologia, alquimia e operações técnicas; a existência de um nome comum não faz deles uma obra uniforme.",listOf(1)),
                HistorySection("Transmissão medieval","Textos, fragmentos e atribuições circularam em línguas e ambientes diferentes. A preservação latina do Asclepius e as tradições árabes ligadas a Hermes contribuíram para a sua receção. A Tábua de Esmeralda pertence a uma história textual própria e não deve ser apresentada como uma inscrição egípcia antiquíssima de proveniência demonstrada. Data de composição, manuscrito conservado e atribuição religiosa são problemas distintos. O estudo da transmissão deve evitar inventar uma cadeia secreta e contínua onde a documentação apenas permite identificar testemunhos separados.",listOf(1,3)),
                HistorySection("Florença · 1463 e 1471","Em 1463, Marsilio Ficino traduziu para latim tratados do Corpus Hermeticum a pedido de Cosimo de’ Medici. A primeira impressão dessa tradução surgiu em Treviso, em 1471. Ficino inseria Hermes numa genealogia de sabedoria antiga e aproximava os textos do platonismo e do cristianismo. Esta interpretação faz parte da história intelectual renascentista; não comprova a antiguidade extrema que se atribuía ao autor. A circulação impressa ampliou os públicos e tornou o hermetismo parte dos debates europeus sobre religião e filosofia.",listOf(2,3)),
                HistorySection("Crítica histórica e receções modernas","No início do século XVII, Isaac Casaubon contestou a cronologia antiga atribuída aos escritos herméticos a partir da sua linguagem e contexto. O episódio é importante porque mostra a diferença entre uma genealogia venerada e a datação crítica dos textos. As utilizações modernas de Hermes, de correspondências e de símbolos alquímicos retomam materiais antigos, mas também os transformam. Não se deve atribuir automaticamente aos textos greco-egípcios qualquer princípio de uma escola esotérica recente. A influência cultural é um objeto histórico; a eficácia sobrenatural das práticas é uma alegação distinta.",listOf(1,2)),
            ),sources=listOf(
                HistorySource("Cambridge University Press · Hermetica","https://www.cambridge.org/core/books/hermetica/A2779DE70B173114CC8669BEB3CF507D","Referência académica; tradução moderna não incluída"),
                HistorySource("Stanford Encyclopedia · Marsilio Ficino","https://plato.stanford.edu/entries/ficino/","Estudo histórico"),
                HistorySource("Sebastiano Gentile · The Reappearance of Hermes in Fifteenth-Century Florence","https://www.journals.uchicago.edu/doi/10.1086/731904","Estudo histórico"),
            ),related=listOf("esotericism","occultism","ancient-philosophy"),concepts="Nous · cosmos · conhecimento · receção textual",conceptItems=listOf(HistoryConcept("Nous","O Intelecto ou Mente divina, princípio ordenador do universo nos textos herméticos. O nous é também a faculdade humana capaz de conhecer Deus: conhecer-se a si mesmo é, nesses textos, o começo de conhecer o todo."),HistoryConcept("Cosmos","O mundo ordenado e vivo, imagem do divino e ligado ao humano por simpatias e correspondências: o que está em baixo é como o que está em cima, na fórmula da Tábua de Esmeralda. A astrologia e a alquimia herméticas nascem desta visão de um todo interligado."),HistoryConcept("Conhecimento","No hermetismo, conhecer não é acumular informação: é uma transformação de quem conhece, uma gnose que libertaria a alma da ignorância e do destino astral. Os diálogos herméticos apresentam esse saber como revelação ensinada de mestre a discípulo."),HistoryConcept("Receção textual","A história da transmissão e das leituras dos textos herméticos: escritos greco-egípcios dos primeiros séculos, guardados por copistas, traduzidos em Florença por Marsilio Ficino (1463) e lidos no Renascimento como sabedoria antiquíssima de Hermes Trismegisto — até a filologia moderna repor a sua data real."))),
        HistoryArticle(id="ancient-philosophy",title="Filosofia antiga",symbol="Φ",description="Escolas gregas e romanas, debate racional e transmissão dos textos.",area=false,
            sections=listOf(
                HistorySection("Séculos VI–V a.C. · os primeiros debates gregos","Pensadores hoje chamados pré-socráticos investigaram natureza, mudança e conhecimento em cidades como Mileto e Éfeso, no mundo grego do Mediterrâneo. A etiqueta é posterior e não designa um grupo com doutrina única. Grande parte dos escritos perdeu-se: o que resta inclui fragmentos citados e testemunhos de autores posteriores. Por isso, uma reconstrução deve identificar quando depende de um intermediário. A novidade das perguntas não significa que estes pensadores tenham separado de forma absoluta religião, poesia e investigação da natureza.",listOf(1)),
                HistorySection("Atenas · Sócrates, Platão e Aristóteles","Sócrates não deixou obras escritas; os retratos literários feitos por outros autores não são transcrições neutras. Platão usou o diálogo para discutir justiça, conhecimento e educação. Aristóteles desenvolveu investigações de ética, lógica, política e natureza. A República e a Ética a Nicómaco são referências destas tradições, sem esgotarem os debates antigos. O estudo deve distinguir a posição de uma personagem num diálogo da posição atribuída ao autor e deve reconhecer os problemas de edição e transmissão dos tratados.",listOf(1,3)),
                HistorySection("Séculos V–IV a.C. · vidas e instituições","Sócrates foi julgado e executado em Atenas em 399 a.C.; a forma como Platão e outros o representam faz parte da história da sua receção. Aristóteles nasceu em Estagira, em 384 a.C., estudou na Academia de Platão e desenvolveu depois o seu próprio ensino. Morreu em 322 a.C. Estes pontos de referência ajudam a situar os debates num mundo de cidades, guerras e instituições educativas. As escolas não eram universidades modernas, e os textos conservados não devem ser tratados como gravações diretas das aulas. O conhecimento disponível sobre cada autor depende dos diferentes tipos de testemunho que sobreviveram.",listOf(4,5)),
                HistorySection("Por volta de 300 a.C. · escolas helenísticas","Zenão de Cítio fundou a escola estoica em Atenas por volta de 300 a.C. O nome deriva da stoa, o pórtico onde se ensinava. Cleantes e Crisipo foram importantes sucessores. Os estoicos relacionavam lógica, física e ética; não tratavam apenas de técnicas para controlar emoções. A concorrência com epicuristas, céticos e outras escolas fez da filosofia uma prática de discussão e formação. As teses sobre a natureza e o destino pertencem aos seus sistemas filosóficos e não ao consenso científico atual.",listOf(2)),
                HistorySection("Roma e heranças posteriores","Séneca, Epicteto e Marco Aurélio são referências do estoicismo no mundo romano. O Manual conserva ensinamentos de Epicteto organizados por Arriano; as Meditações são apontamentos de Marco Aurélio. Não são capítulos de uma mesma obra nem dizem sempre o mesmo. A receção posterior em autores cristãos e em pensadores renascentistas voltou a selecionar e reinterpretar os materiais antigos. Manuscritos, traduções e edições explicam como estes textos chegaram até nós. As versões contemporâneas de estoicismo devem, por isso, distinguir-se das comunidades e argumentos da Antiguidade.",listOf(2)),
            ),sources=listOf(
                HistorySource("Stanford Encyclopedia · Presocratic Philosophy","https://plato.stanford.edu/entries/presocratics/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Stoicism","https://plato.stanford.edu/entries/stoicism/","Estudo histórico"),
                HistorySource("MIT Internet Classics Archive · Autores e obras","https://classics.mit.edu/Browse/index.html","Arquivo de traduções; verificar edição"),
                HistorySource("Stanford Encyclopedia · Socrates","https://plato.stanford.edu/entries/socrates/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Aristotle","https://plato.stanford.edu/entries/aristotle/","Estudo histórico"),
            ),related=listOf("philosophy","hermeticism","atheism"),concepts="Ética · virtude · razão · conhecimento · vida boa",conceptItems=listOf(HistoryConcept("Ética","A reflexão sobre como viver e agir bem, que nas escolas antigas era inseparável da filosofia como um todo: estoicos, epicuristas, platónicos e aristotélicos propunham terapias da alma e exercícios espirituais, e não apenas teorias."),HistoryConcept("Virtude","A excelência do caráter (arete): a disposição estável de agir bem — coragem, justiça, temperança e prudência são as virtudes cardeais clássicas. Para Aristóteles, a virtude adquire-se pelo hábito, como uma arte que se aprende praticando."),HistoryConcept("Razão","O logos: a faculdade que ordena o discurso, conhece a verdade e, para muitos filósofos antigos, participa da ordem racional do próprio cosmos. Viver segundo a razão é o programa comum, com sentidos diferentes, de platónicos e estoicos."),HistoryConcept("Conhecimento","A questão de saber o que podemos realmente conhecer e como: do só sei que nada sei de Sócrates à teoria platónica das Formas e ao ceticismo que suspende o juízo, a teoria do conhecimento nasce como problema na filosofia antiga."),HistoryConcept("Vida boa","A eudaimonia: felicidade entendida como florescimento de uma vida inteira bem vivida, e não como um prazer passageiro. É a pergunta que organiza a ética antiga: em que consiste a vida boa, e que exercícios e escolhas conduzem a ela?"))),
        HistoryArticle(id="atheism",title="Ateísmo e agnosticismo",symbol="∴",description="História da crítica religiosa, da dúvida e das posições não teístas.",area=false,
            sections=listOf(
                HistorySection("Definir antes de classificar","Ateísmo e agnosticismo não são religiões únicas nem organizações com um fundador comum. Ateísmo pode designar ausência de crença em deuses ou a tese de que não existem deuses, conforme o uso. Agnosticismo pode referir-se à suspensão do juízo ou aos limites do conhecimento. Uma pessoa sem filiação religiosa não é necessariamente ateia. Identificar estas diferenças evita projetar categorias atuais sobre autores antigos ou atribuir uma mesma posição a todos os participantes num debate.",listOf(1)),
                HistorySection("Antiguidade e crítica dos argumentos","A filosofia antiga incluiu críticas das representações tradicionais dos deuses e debates sobre natureza e causalidade. As acusações de impiedade não provam por si só ateísmo no sentido moderno. O epicurismo, por exemplo, não deve ser confundido automaticamente com negação de todos os deuses. Fontes fragmentárias e relatos de adversários exigem cautela. A história da não crença deve estudar argumentos e condições sociais, sem inventar uma escola secreta que teria mantido sempre uma doutrina idêntica ao longo dos séculos.",listOf(1,3)),
                HistorySection("Século XVIII · Hume e a religião","David Hume examinou argumentos sobre Deus, milagres, moralidade e origem das crenças. A História Natural da Religião foi publicada em 1757; os Diálogos sobre a Religião Natural, em 1779, depois da sua morte. A interpretação da posição pessoal de Hume continua em debate: chamar-lhe simplesmente ateu pode ocultar diferenças entre a crítica de um argumento e a defesa de uma tese metafísica. Os textos documentam a história do ceticismo e das controvérsias intelectuais britânicas do século XVIII.",listOf(2)),
                HistorySection("Paris no século XVIII · d’Holbach","Paul-Henri Thiry, barão d’Holbach, nasceu em 1723 e tornou-se uma figura do Iluminismo francês. As reuniões que promoveu em Paris aproximaram autores e leitores de posições diferentes. Os seus escritos formularam uma visão materialista e determinista e uma crítica da religião organizada. O caso permite estudar a não crença através de redes sociais, traduções, edição e controvérsia, sem presumir que todos os iluministas eram ateus. Também mostra que uma posição filosófica sobre a matéria e a causalidade não se confunde com o conjunto dos resultados da ciência contemporânea.",listOf(5)),
                HistorySection("1869 e os debates contemporâneos","Thomas Henry Huxley introduziu o termo agnóstico em 1869 no contexto britânico. O significado público evoluiu e não ficou sob controlo de quem criou a palavra. Hoje, ateus, agnósticos, humanistas e pessoas religiosas continuam a discutir prova, interpretação e limites da razão. Uma descrição histórica não deve transformar a ausência de demonstração de uma crença numa biografia falsa dos seus seguidores, nem atribuir automaticamente uma posição religiosa ao método científico. A Sophia apresenta estas perspetivas com os mesmos critérios documentais usados para estudar as tradições religiosas.",listOf(1,4)),
            ),sources=listOf(
                HistorySource("Stanford Encyclopedia · Atheism and Agnosticism","https://plato.stanford.edu/entries/atheism-agnosticism/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Hume on Religion","https://plato.stanford.edu/entries/hume-religion/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Presocratic Philosophy","https://plato.stanford.edu/entries/presocratics/","Estudo histórico"),
                HistorySource("Bernard Lightman · Huxley and Scientific Agnosticism","https://doi.org/10.1017/S0007087402004715","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Baron d’Holbach","https://plato.stanford.edu/entries/holbach/","Estudo histórico"),
            ),related=listOf("philosophy","ancient-philosophy","religions"),concepts="Crença · evidência · ceticismo · suspensão do juízo",conceptItems=listOf(HistoryConcept("Crença","Neste campo, crença designa a aceitação de que Deus ou deuses existem. O ateísmo é a ausência dessa crença — ou, numa versão mais forte, a convicção de que não existem; o agnosticismo suspende a resposta, por considerar a questão indecidível com os dados disponíveis."),HistoryConcept("Evidência","O critério central do debate moderno: que razões e provas sustentam ou enfraquecem a crença em Deus? Argumentos clássicos (cosmológico, do desígnio) e objeções (problema do mal, parcimónia) avaliam-se pela qualidade das evidências apresentadas."),HistoryConcept("Ceticismo","A atitude de examinar antes de aceitar: herdeira dos céticos antigos, aplica às afirmações religiosas as mesmas exigências de prova usadas noutros domínios. Nem todo o cético é ateu, mas o método cético alimenta historicamente a dúvida religiosa."),HistoryConcept("Suspensão do juízo","A epoché dos céticos antigos, retomada pelo agnosticismo: perante uma questão sem evidência decisiva, não afirmar nem negar. Thomas Huxley cunhou o termo agnóstico (1869) exatamente para esta posição de honestidade intelectual."))),
        HistoryArticle(id="religions",title="Religiões",symbol="⌂",description="História comparada das comunidades, instituições, práticas e textos.",area=true,
            sections=listOf(
                HistorySection("Uma categoria com história","Religião é uma categoria de análise cujo significado mudou ao longo do tempo. Não existe uma definição única aceite por todos os investigadores. Defini-la apenas como crença num criador exclui tradições que normalmente são estudadas como religiões. O estudo histórico observa práticas, instituições, narrativas, objetos e formas de pertença, sem pressupor que todas tenham a mesma estrutura.",listOf(1)),
                HistorySection("Tempos e lugares diferentes","O antigo Israel, o norte da Índia, a China e a Arábia do século VII são contextos distintos de formação de tradições. Judaísmo, cristianismo e Islão têm ligações históricas entre si; isso não elimina as suas diferenças. Hinduísmo, budismo, taoismo e confucionismo também se desenvolveram através de encontros e debates. As páginas de cada tradição permitem seguir essas histórias sem construir uma cronologia única e artificial para todas as crenças.",listOf(1,2)),
                HistorySection("Como comparar com rigor","Uma instituição pode mudar de língua, território ou forma de organização sem desaparecer. A difusão de uma religião também pode envolver comércio, migração, patrocínio político e conflito. Uma narrativa sagrada e um documento administrativo respondem a perguntas diferentes. Para verificar uma afirmação, importa saber quem produziu a fonte, quando a produziu e se há testemunhos independentes. As referências abaixo orientam o estudo; não são livros integrais disponíveis na Biblioteca.",listOf(1,2)),
            ),sources=listOf(
                HistorySource("Stanford Encyclopedia · The Concept of Religion","https://plato.stanford.edu/entries/concept-religion/","Estudo histórico"),
                HistorySource("PBS · Global Connections: Religion","https://www.pbs.org/wgbh/globalconnections/mideast/themes/religion/index.html","Estudo histórico"),
            ),related=listOf("hinduism","buddhism","judaism","christianity","islam","taoism","confucianism","atheism"),concepts="Ritual · mito · texto sagrado · comunidade",conceptItems=listOf(HistoryConcept("Ritual","Sequência de gestos, palavras e objetos com forma prescrita, repetida pela comunidade para marcar o sagrado, o tempo e as passagens da vida: nascimento, casamento, morte. O estudo comparado dos rituais é uma das portas de entrada na história das religiões."),HistoryConcept("Mito","Narrativa fundadora que conta as origens do mundo, dos deuses e das instituições, dando sentido ao presente. Na história das religiões, mito não significa mentira: é a história sagrada que uma comunidade conserva e reactualiza nos seus ritos."),HistoryConcept("Texto sagrado","O texto que uma comunidade reconhece como revelação ou autoridade máxima — escrito, como a Bíblia ou o Corão, ou transmitido oralmente por gerações, como os Vedas. À volta dele nascem cânones, comentários e disputas de interpretação."),HistoryConcept("Comunidade","As religiões vivem em comunidades — congregações, ordens, escolas, famílias — que transmitem práticas e memórias, formam especialistas (sacerdotes, monges, mestres) e negociam a mudança ao longo dos séculos."))),
        HistoryArticle(id="philosophy",title="Filosofia",symbol="Φ",description="Argumentos, escolas e modos de vida em diferentes contextos históricos.",area=true,
            sections=listOf(
                HistorySection("Investigar e discutir","Filosofia não é uma religião única nem uma lista de opiniões sem contexto. No mundo grego dos séculos VI e V a.C., autores discutiram natureza e conhecimento através de propostas rivais. A expressão pré-socrático é uma ferramenta posterior para organizar esse passado. O caráter fragmentário das fontes obriga a distinguir palavras conservadas, paráfrases e reconstruções.",listOf(1)),
                HistorySection("Para além de uma só geografia","Os debates chineses associados a Confúcio e Laozi e as discussões indianas preservadas em diferentes tradições também pertencem à história da reflexão filosófica. Não são cópias de escolas gregas. Questões sobre conduta, linguagem, conhecimento e libertação foram formuladas em línguas e instituições diferentes. Comparar exige preservar essas diferenças, em vez de traduzir todos os termos como se significassem exatamente a mesma coisa.",listOf(2,3)),
                HistorySection("Leitura crítica e transmissão","Platónicos, aristotélicos, estoicos e céticos divergem entre si. A história dos argumentos inclui as condições em que se ensinavam e os caminhos pelos quais manuscritos e traduções foram preservados. A receção moderna seleciona frequentemente apenas certas ideias. Nas páginas de Filosofia antiga e de Ateísmo e agnosticismo podes acompanhar exemplos concretos desta relação entre texto, debate e interpretação. Uma tese filosófica deve ser identificada como tal, não anunciada como resultado experimental.",listOf(1)),
            ),sources=listOf(
                HistorySource("Stanford Encyclopedia · Presocratic Philosophy","https://plato.stanford.edu/entries/presocratics/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Confucius","https://plato.stanford.edu/entries/confucius/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Laozi","https://plato.stanford.edu/entries/laozi/","Estudo histórico"),
            ),related=listOf("ancient-philosophy","confucianism","taoism","hinduism","atheism"),concepts="Argumento · lógica · escola · crítica",conceptItems=listOf(HistoryConcept("Argumento","Uma sequência de razões oferecidas para sustentar uma conclusão, que pode ser examinada, contestada e aperfeiçoada. É a ferramenta de trabalho da filosofia em todas as épocas: mesmo quem discorda partilha o dever de dar razões."),HistoryConcept("Lógica","O estudo das formas válidas de inferência: o que se segue de quê, e com que necessidade. Nascida com Aristóteles e desenvolvida por estoicos, escolásticos e modernos, é a disciplina que guarda o pensamento rigoroso."),HistoryConcept("Escola","Uma tradição de pensamento com mestres, textos e exercícios próprios: na Antiguidade, a Academia de Platão ou o Jardim de Epicuro eram também comunidades de vida; hoje, o termo designa correntes que partilham métodos e referências."),HistoryConcept("Crítica","O exame dos limites e das condições do que pensamos saber — exemplarmente, nas três críticas de Kant. Em sentido lato, é a recusa de aceitar uma ideia só pela autoridade de quem a afirma."))),
        HistoryArticle(id="mysticism",title="Misticismo",symbol="◉",description="Práticas contemplativas e relatos de transformação em contextos religiosos diversos.",area=true,
            sections=listOf(
                HistorySection("Uma designação comparativa","Misticismo reúne práticas, textos e relatos de transformação que não formam uma religião única. Investigadores discutem se experiências descritas em tradições diferentes podem ser comparadas diretamente ou se a linguagem e a cultura moldam aquilo que é vivido e narrado. A existência de um testemunho é um facto documental; a interpretação sobrenatural do testemunho é uma questão diferente.",listOf(1)),
                HistorySection("Percursos históricos distintos","O sufismo desenvolveu vias espirituais no interior de comunidades islâmicas. A Cabala pertence à história judaica e conheceu importantes desenvolvimentos medievais. A contemplação cristã e as práticas de meditação budistas têm outros vocabulários e instituições. Aproximar todos estes percursos pela palavra misticismo pode ser útil para formular perguntas, mas não permite atribuir-lhes a mesma doutrina nem uma origem secreta comum.",listOf(1,2)),
                HistorySection("Textos, pessoas e investigação","A investigação estuda mestres, comunidades, regras de prática, poemas e tratados, considerando também quem podia transmitir ou legitimar uma experiência. Os relatos de união com Deus ou de libertação pertencem às interpretações das respetivas tradições. Estudos sobre meditação não validam automaticamente todas as afirmações metafísicas associadas a uma escola. As páginas relacionadas apresentam lugares e períodos concretos, com referências para aprofundar a leitura.",listOf(1,2)),
            ),sources=listOf(
                HistorySource("Stanford Encyclopedia · Mysticism","https://plato.stanford.edu/entries/mysticism/","Estudo histórico"),
                HistorySource("Biblioteca Nacional de Israel · Sufism","https://www.nli.org.il/en/discover/islam/islamic-studies/sufism","Estudo histórico"),
            ),related=listOf("islam","judaism","christianity","buddhism","hinduism"),concepts="Contemplação · êxtase · união · via negativa",conceptItems=listOf(HistoryConcept("Contemplação","A atenção silenciosa e sustentada ao divino ou ao real, presente em tradições muito diferentes: da oração cristã à meditação budista e ao dhikr sufi. Procura conhecer por presença, e não por conceitos."),HistoryConcept("Êxtase","O estado de sair de si relatado por místicos de várias tradições: absorção intensa, perda temporária da noção ordinária do eu e impressão de contacto direto com o absoluto. Os relatos são depois interpretados na linguagem de cada tradição."),HistoryConcept("União","O objetivo descrito por muitos místicos: a união da alma com Deus na mística cristã, a realização da não-dualidade no hinduísmo e em partes do budismo, a extinção no divino (fana) no sufismo. Cada tradição define de modo diferente o que se une e o que permanece distinto."),HistoryConcept("Via negativa","A teologia apofática: falar de Deus, ou do absoluto, pelo que ele não é, porque qualquer conceito o limitaria. Do Pseudo-Dionísio a Mestre Eckhart, é a via que prefere o silêncio e a negação à afirmação inadequada."))),
        HistoryArticle(id="esotericism",title="Esoterismo",symbol="◇",description="Circulação de textos, símbolos e saberes reservados na história ocidental.",area=true,
            sections=listOf(
                HistorySection("Um campo histórico plural","Esoterismo é uma categoria usada para estudar correntes e repertórios diversos. Não identifica uma instituição universal nem comprova que todos os grupos tenham conservado o mesmo ensinamento. Textos herméticos, platonismos, interpretações simbólicas e práticas de transformação foram combinados de maneiras diferentes. Os próprios limites do campo são objeto de discussão académica.",listOf(1)),
                HistorySection("Antiguidade, Idade Média e Renascimento","A receção dos escritos atribuídos a Hermes oferece um caso documentado. Autores renascentistas como Marsilio Ficino procuraram relacionar sabedoria antiga, platonismo e cristianismo. A tradução latina de tratados herméticos, realizada em Florença em 1463, teve grande circulação posterior. O facto de os intérpretes acreditarem numa genealogia remota deve ser distinguido da datação crítica dos textos.",listOf(2,3)),
                HistorySection("Como reconhecer continuidades e invenções","A semelhança entre símbolos não prova uma transmissão direta entre duas sociedades. Para reconstruir uma ligação são necessários manuscritos, edições, correspondência ou outros testemunhos. As apropriações modernas fazem parte da história cultural, mas não devem ser projetadas retroativamente sobre os autores antigos. Nesta área, capas e símbolos da Sophia são elementos de orientação editorial, sem valor de prova documental. A página de Hermetismo permite seguir uma história textual concreta.",listOf(1,2)),
            ),sources=listOf(
                HistorySource("Nicholas Goodrick-Clarke · The Western Esoteric Traditions","https://academic.oup.com/book/9553","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Marsilio Ficino","https://plato.stanford.edu/entries/ficino/","Estudo histórico"),
                HistorySource("Sebastiano Gentile · The Reappearance of Hermes","https://www.journals.uchicago.edu/doi/10.1086/731904","Estudo histórico"),
            ),related=listOf("hermeticism","occultism","judaism","ancient-philosophy"),concepts="Iniciação · símbolo · segredo · correspondências",conceptItems=listOf(HistoryConcept("Iniciação","O rito ou processo gradual de entrada num saber ou grupo reservado: provas, juramentos e revelações por graus. Das escolas antigas às ordens modernas, a iniciação marca a fronteira entre o público e o reservado."),HistoryConcept("Símbolo","Imagem ou objeto que remete para um sentido para lá do literal, e que só se entrega a quem aprende a lê-lo. No esoterismo, os símbolos são tratados como linguagem precisa do invisível, e não como mera decoração."),HistoryConcept("Segredo","A reserva do saber: por proteção de quem não está preparado, por perigo do uso errado, ou porque a experiência não cabe em palavras. A história do esoterismo é também a história de como os segredos circulam: manuscritos copiados, sociedades discretas, impressos disfarçados."),HistoryConcept("Correspondências","A rede de afinidades que ligaria todas as partes do universo — planetas e metais, cores e virtudes, letras e destinos — resumida na fórmula segundo a qual o que está em cima é como o que está em baixo. É a gramática comum da astrologia, da alquimia e da magia renascentistas."))),
        HistoryArticle(id="occultism",title="Ocultismo",symbol="✶",description="Movimentos e práticas ligados a saberes ocultos, com atenção à proveniência.",area=true,
            sections=listOf(
                HistorySection("Nomes e fronteiras","Ocultismo é uma designação histórica ampla, frequentemente associada a práticas e movimentos que reivindicam conhecimentos ou forças ocultas. Não equivale a todas as religiões nem a todo o misticismo. Os seus usos sobrepõem-se por vezes ao campo do esoterismo, mas devem ser examinados em cada época. A existência de uma crença numa força oculta não demonstra a existência dessa força.",listOf(1)),
                HistorySection("Reutilizar o passado","Materiais herméticos, alquímicos e astrológicos foram recebidos e reorganizados por leitores de épocas posteriores. Na Europa renascentista, as interpretações de autores como Ficino mostram como saberes antigos podiam ser articulados com preocupações cristãs e filosóficas. Movimentos modernos voltaram a selecionar esses repertórios. Uma afirmação de iniciação milenar deve ser tratada como reivindicação do grupo até que a sua transmissão seja documentada.",listOf(1,2)),
                HistorySection("Londres, 1888 · a Golden Dawn","A Hermetic Order of the Golden Dawn foi fundada em Inglaterra em 1888; o seu primeiro templo, Isis-Urania, abriu em Londres. William Wynn Westcott, Samuel Liddell MacGregor Mathers e William Robert Woodman estiveram ligados à fundação. O sistema reuniu símbolos e materiais de proveniências diversas, incluindo interpretações da Cabala, e admitiu homens e mulheres. A instituição conheceu divisões e grupos sucessores. Este exemplo documenta uma organização moderna concreta: o uso do adjetivo hermético não demonstra que ela seja uma instituição sobrevivente do Egito antigo, nem que todas as suas práticas se encontrem no Corpus Hermeticum.",listOf(3)),
                HistorySection("Documentação e alegações","O estudo histórico usa publicações, arquivos de associações, biografias e objetos, incluindo relatos de polémicas. Uma fonte hostil e uma fonte produzida pelo próprio grupo exigem leitura crítica. Não se inventam rituais, citações ou linhagens para preencher lacunas. Também não se apresentam práticas ocultistas como tratamentos médicos. As ligações a Hermetismo e Esoterismo oferecem percursos documentados para compreender a circulação e a transformação das ideias.",listOf(1,2)),
            ),sources=listOf(
                HistorySource("Nicholas Goodrick-Clarke · The Western Esoteric Traditions","https://academic.oup.com/book/9553","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Marsilio Ficino","https://plato.stanford.edu/entries/ficino/","Estudo histórico"),
                HistorySource("Nevill Drury · New Light: The Rise of the Golden Dawn","https://academic.oup.com/book/5515/chapter-abstract/148439443","Estudo histórico"),
            ),related=listOf("esotericism","hermeticism","spiritism"),concepts="Magia · astrologia · alquimia · invocação",conceptItems=listOf(HistoryConcept("Magia","Conjunto de práticas que procuram agir sobre o mundo, ou sobre os espíritos, por meios não ordinários: rituais, palavras, objetos e tempos escolhidos. O ocultismo dos séculos XIX e XX sistematizou tradições mágicas mais antigas em ordens e manuais."),HistoryConcept("Astrologia","A leitura das posições e dos movimentos dos astros como sinais do carácter e do destino, herdada da Antiguidade e integrada no ocultismo como uma das suas ciências clássicas, ao lado da alquimia."),HistoryConcept("Alquimia","A arte de transformar a matéria — emblematicamente, produzir ouro ou o elixir da longa vida — lida por muitos praticantes também como caminho de transformação interior. Laboratório e símbolo caminham juntos nos textos alquímicos."),HistoryConcept("Invocação","A chamada ritual de uma entidade — anjo, espírito, deus — para obter presença, resposta ou auxílio. Ocupa o centro da magia cerimonial e distingue-se da evocação em alguns sistemas, que reservam os dois termos para tipos diferentes de entidades."))),
        HistoryArticle(id="spirituality",title="Espiritualidade",symbol="❋",description="História das buscas de sentido e das suas formas religiosas e não religiosas.",area=true,
            sections=listOf(
                HistorySection("Um termo com vários usos","Espiritualidade pode designar práticas religiosas, formas de cultivo interior e buscas pessoais de sentido. O seu alcance varia entre comunidades e épocas; não corresponde a uma única religião nem implica que exista acordo sobre o que é um espírito. O estudo observa como as pessoas descrevem a experiência, organizam práticas e criam instituições. A realidade histórica dessas descrições não confirma automaticamente as entidades de que falam.",listOf(1,2)),
                HistorySection("Práticas em contextos concretos","Contemplação cristã, meditação budista, devoção hindu e vias sufistas são exemplos de percursos distintos. Cada um tem textos, mestres e formas de transmissão próprios. Também existem posições seculares que procuram uma vida com significado sem aceitar divindades. Colocar estes percursos numa mesma área facilita a comparação, mas não os transforma em variantes de uma doutrina universal comprovada.",listOf(1,2)),
                HistorySection("Século XIX · o caso espírita","O espiritismo de Allan Kardec é um caso histórico específico e não sinónimo de toda a espiritualidade. A publicação de O Livro dos Espíritos em Paris, em 1857, e a criação de uma revista e sociedade em 1858 permitem estudar a organização do movimento. A mediunidade e a sobrevivência do espírito são ensinamentos e alegações dessa tradição. Outras formas de espiritualidade seguem caminhos diferentes. As páginas relacionadas permitem explorá-las sem confundir história, interpretação e prova científica.",listOf(3)),
            ),sources=listOf(
                HistorySource("Stanford Encyclopedia · Mysticism","https://plato.stanford.edu/entries/mysticism/","Estudo histórico"),
                HistorySource("Stanford Encyclopedia · Atheism and Agnosticism","https://plato.stanford.edu/entries/atheism-agnosticism/","Estudo histórico"),
                HistorySource("Psi Encyclopedia · Allan Kardec","https://psi-encyclopedia.spr.ac.uk/articles/allan-kardec/","Perspetiva da Society for Psychical Research; contextualizar"),
            ),related=listOf("spiritism","buddhism","christianity","hinduism","islam","atheism"),concepts="Sentido · experiência · prática · transcendência",conceptItems=listOf(HistoryConcept("Sentido","A procura de significado para a vida: de onde venho, para que vivo, como enfrentar o sofrimento e a morte. A espiritualidade, religiosa ou não, organiza-se em volta destas perguntas, mesmo quando recusa as respostas institucionais."),HistoryConcept("Experiência","O vivido em primeira pessoa: momentos de presença, gratidão, assombro ou unidade que as pessoas descrevem como espirituais. O acento contemporâneo na experiência distingue a espiritualidade vivida da religião apenas herdada."),HistoryConcept("Prática","Os gestos regulares que sustentam a busca: meditar, rezar, caminhar, escrever um diário, guardar silêncio. Sem prática, a espiritualidade fica uma ideia; com ela, torna-se um modo de vida que se treina."),HistoryConcept("Transcendência","Aquilo que excede o eu e o imediato — Deus, o absoluto, a natureza, a humanidade — e diante do qual a pessoa se sente parte de algo maior. Mesmo espiritualidades sem deuses falam de uma transcendência horizontal: o outro, o mundo, o futuro."))),
    )
}
